/// The definition the engine runs.
pub struct FileUploadWorkflow {
    #[allow(dead_code)]
    services: Arc<WorkflowServices>,
    #[allow(dead_code)]
    actions: Arc<dyn FileUploadActions>,
}

impl FileUploadWorkflow {
    /// A definition writing through `services` and calling `actions` for what the schema cannot say.
    pub fn new(services: Arc<WorkflowServices>, actions: Arc<dyn FileUploadActions>) -> Self {
        Self { services, actions }
    }
}

fn to_json<T: serde::Serialize>(value: &T) -> ServiceResult<Value> {
    serde_json::to_value(value).map_err(|e| ServiceError::Internal(e.to_string()))
}

#[allow(dead_code)]
fn record_id(call: &Call<'_>) -> ServiceResult<String> {
    call.id.clone().ok_or_else(|| ServiceError::Validation(format!("step `{}` names no record", call.step)))
}

/// The parameters of a step as fields to write: everything but the record's `id`.
#[allow(dead_code)]
fn fields_of(params: &Value) -> HashMap<String, Value> {
    params.as_object().cloned().unwrap_or_default().into_iter().filter(|(k, _)| k != "id").collect()
}

/// The parameters of a `query` or `fetch` as equality filters, a page size and a sort.
#[allow(dead_code)]
fn filters_of(params: &Value, default_limit: u32) -> (HashMap<String, String>, u32) {
    let mut filters = HashMap::new();
    let mut limit = default_limit;
    for (k, v) in params.as_object().into_iter().flatten() {
        match k.as_str() {
            "_limit" => limit = v.as_u64().map(|n| n as u32).unwrap_or(default_limit),
            "_order" => {
                // `created_at DESC` is the filter map's `sort=-created_at`.
                let text = v.as_str().unwrap_or_default();
                let mut parts = text.split_whitespace();
                if let Some(field) = parts.next() {
                    let desc = parts.next().is_some_and(|d| d.eq_ignore_ascii_case("desc"));
                    filters.insert("sort".to_string(), format!("{}{field}", if desc { "-" } else { "" }));
                }
            }
            _ => {
                let text = match v { Value::String(s) => s.clone(), other => other.to_string() };
                filters.insert(k.clone(), text);
            }
        }
    }
    (filters, limit)
}

#[async_trait]
impl WorkflowDefinition for FileUploadWorkflow {
    fn spec(&self) -> &WorkflowSpec {
        static SPEC: OnceLock<WorkflowSpec> = OnceLock::new();
        SPEC.get_or_init(|| WorkflowSpec::from_json(FILE_UPLOAD_SPEC))
    }

    #[allow(unused_variables)]
    async fn perform(&self, ctx: &WriteCtx, call: &Call<'_>) -> ServiceResult<Value> {
        match call.step {
            "load_bucket" => {
                let (filters, limit) = filters_of(call.params, 1);
                let (rows, _) = self.services.bucket.list(1, limit, filters).await?;
                match rows.into_iter().next() {
                    Some(found) => to_json(&found),
                    None => Err(ServiceError::NotFound),
                }
            }
            "calculate_checksum" => self.actions.calculate_sha256(ctx, call.params, call.context).await,
            "check_duplicate_content" => {
                let (filters, limit) = filters_of(call.params, 1);
                let (rows, _) = self.services.content_hash.list(1, limit, filters).await?;
                match rows.into_iter().next() {
                    Some(found) => to_json(&found),
                    None => Err(ServiceError::NotFound),
                }
            }
            "use_existing_content" => {
                let id = record_id(call)?;
                match self.services.content_hash.partial_update(&id, fields_of(call.params)).await? {
                    Some(saved) => to_json(&saved),
                    None => Err(ServiceError::NotFound),
                }
            }
            "detect_mime_type" => self.actions.detect_mime(ctx, call.params, call.context).await,
            "load_quota" => {
                let (filters, limit) = filters_of(call.params, 1);
                let (rows, _) = self.services.user_quota.list(1, limit, filters).await?;
                match rows.into_iter().next() {
                    Some(found) => to_json(&found),
                    None => Err(ServiceError::NotFound),
                }
            }
            "create_default_quota" => {
                let dto: crate::presentation::dto::CreateUserQuotaDto = serde_json::from_value(call.params.clone())
                    .map_err(|e| ServiceError::Validation(format!("step `{}`: the parameters do not make a CreateUserQuotaDto: {e}", call.step)))?;
                let saved = self.services.user_quota.create(dto).await?;
                to_json(&saved)
            }
            "create_file_record" => {
                let dto: crate::presentation::dto::CreateStoredFileDto = serde_json::from_value(call.params.clone())
                    .map_err(|e| ServiceError::Validation(format!("step `{}`: the parameters do not make a CreateStoredFileDto: {e}", call.step)))?;
                let saved = self.services.stored_file.create(dto).await?;
                to_json(&saved)
            }
            "store_content" => self.actions.store_file(ctx, call.params, call.context).await,
            "create_content_hash" => {
                let dto: crate::presentation::dto::CreateContentHashDto = serde_json::from_value(call.params.clone())
                    .map_err(|e| ServiceError::Validation(format!("step `{}`: the parameters do not make a CreateContentHashDto: {e}", call.step)))?;
                let saved = self.services.content_hash.create(dto).await?;
                to_json(&saved)
            }
            "link_content_hash" => {
                let id = record_id(call)?;
                match self.services.stored_file.partial_update(&id, fields_of(call.params)).await? {
                    Some(saved) => to_json(&saved),
                    None => Err(ServiceError::NotFound),
                }
            }
            "update_file_processing" => self.actions.begin_processing(ctx, call.params, call.context).await,
            "scan_file" => self.actions.scan_for_threats(ctx, call.params, call.context).await,
            "update_scan_complete" => {
                let id = record_id(call)?;
                match self.services.stored_file.partial_update(&id, fields_of(call.params)).await? {
                    Some(saved) => to_json(&saved),
                    None => Err(ServiceError::NotFound),
                }
            }
            "generate_cdn_url" => self.actions.generate_cdn_url(ctx, call.params, call.context).await,
            "update_cdn_info" => {
                let id = record_id(call)?;
                match self.services.stored_file.partial_update(&id, fields_of(call.params)).await? {
                    Some(saved) => to_json(&saved),
                    None => Err(ServiceError::NotFound),
                }
            }
            "mark_file_active" => self.actions.activate_file(ctx, call.params, call.context).await,
            "update_bucket_stats" => {
                let id = record_id(call)?;
                match self.services.bucket.partial_update(&id, fields_of(call.params)).await? {
                    Some(saved) => to_json(&saved),
                    None => Err(ServiceError::NotFound),
                }
            }
            "quarantine_file" => self.actions.quarantine_file(ctx, call.params, call.context).await,
            "rollback_file_record" => {
                let id = record_id(call)?;
                if self.services.stored_file.soft_delete(&id).await? {
                    Ok(serde_json::json!({ "deleted": true, "id": id }))
                } else {
                    Err(ServiceError::NotFound)
                }
            }
            "compensate:delete_stored_content" => self.actions.delete_file(ctx, call.params, call.context).await,
            "compensate:decrement_content_hash" => self.actions.decrement_reference(ctx, call.params, call.context).await,
            "compensate:delete_file_record" => {
                let id = record_id(call)?;
                if self.services.stored_file.soft_delete(&id).await? {
                    Ok(serde_json::json!({ "deleted": true, "id": id }))
                } else {
                    Err(ServiceError::NotFound)
                }
            }
            other => Err(ServiceError::Internal(format!("step `{other}` has no action in FileUpload"))),
        }
    }

    #[allow(unused_variables)]
    async fn function(&self, ctx: &WriteCtx, name: &str, args: &[Value]) -> ServiceResult<Value> {
        match name {
            other => Err(ServiceError::Internal(format!("function `{other}` is not declared by FileUpload"))),
        }
    }
}

